#include "test.hpp"
#include "shell/data_object.hpp"
#include "shell/staging.hpp"
#include <shlwapi.h>
#include <wrl/client.h>
using namespace crackhood;using Microsoft::WRL::ComPtr;
TEST(data_object_invalid_lindex){ComPtr<IDataObject>d;CHECK(SUCCEEDED(CreateDataObject({{NodeKind::File,{"rgh"},{"HDD:\\x"},{"x",false,10}}},IID_PPV_ARGS(&d))));FORMATETC f{static_cast<CLIPFORMAT>(RegisterClipboardFormatW(CFSTR_FILECONTENTS)),nullptr,DVASPECT_CONTENT,999,TYMED_ISTREAM};STGMEDIUM m{};CHECK(d->GetData(&f,&m)==DV_E_LINDEX);}
TEST(data_object_descriptors){ComPtr<IDataObject>d;CHECK(SUCCEEDED(CreateDataObject({{NodeKind::File,{"rgh"},{"HDD:\\x"},{"x",false,123}}},IID_PPV_ARGS(&d))));FORMATETC f{static_cast<CLIPFORMAT>(RegisterClipboardFormatW(CFSTR_FILEDESCRIPTORW)),nullptr,DVASPECT_CONTENT,-1,TYMED_HGLOBAL};STGMEDIUM m{};CHECK(SUCCEEDED(d->GetData(&f,&m)));auto p=static_cast<FILEGROUPDESCRIPTORW*>(GlobalLock(m.hGlobal));CHECK(p->cItems==1);CHECK(p->fgd[0].nFileSizeLow==123);CHECK(std::wstring(p->fgd[0].cFileName)==L"x");GlobalUnlock(m.hGlobal);ReleaseStgMedium(&m);}
TEST(data_object_unknown_format){ComPtr<IDataObject>d;CHECK(SUCCEEDED(CreateDataObject({},IID_PPV_ARGS(&d))));FORMATETC f{CF_TEXT,nullptr,DVASPECT_CONTENT,-1,TYMED_HGLOBAL};CHECK(d->QueryGetData(&f)==DV_E_FORMATETC);}
TEST(data_object_cut_effect){ComPtr<IDataObject>d;CHECK(SUCCEEDED(CreateDataObject({},IID_PPV_ARGS(&d),DROPEFFECT_MOVE)));FORMATETC f{static_cast<CLIPFORMAT>(RegisterClipboardFormatW(CFSTR_PREFERREDDROPEFFECT)),nullptr,DVASPECT_CONTENT,-1,TYMED_HGLOBAL};STGMEDIUM m{};CHECK(SUCCEEDED(d->GetData(&f,&m)));auto p=static_cast<DWORD*>(GlobalLock(m.hGlobal));CHECK(*p==DROPEFFECT_COPY);GlobalUnlock(m.hGlobal);ReleaseStgMedium(&m);}
TEST(drop_target_invalid_destination){ComPtr<IDropTarget>d;CHECK(CreateDropTarget({NodeKind::Directory,{"rgh"},{"HDD:\\..\\escape"},{}},IID_PPV_ARGS(&d))==E_INVALIDARG);}
TEST(data_object_stream_seek){ComPtr<IDataObject>d;CHECK(SUCCEEDED(CreateDataObject({{NodeKind::File,{"rgh"},{"HDD:\\x"},{"x",false,10}}},IID_PPV_ARGS(&d))));FORMATETC f{static_cast<CLIPFORMAT>(RegisterClipboardFormatW(CFSTR_FILECONTENTS)),nullptr,DVASPECT_CONTENT,0,TYMED_ISTREAM};STGMEDIUM m{};CHECK(SUCCEEDED(d->GetData(&f,&m)));LARGE_INTEGER p{};p.QuadPart=-1;CHECK(FAILED(m.pstm->Seek(p,STREAM_SEEK_SET,nullptr)));ULARGE_INTEGER pos{};CHECK(SUCCEEDED(m.pstm->Seek(p,STREAM_SEEK_END,&pos)));CHECK(pos.QuadPart==9);ComPtr<IStream>clone;CHECK(SUCCEEDED(m.pstm->Clone(&clone)));p.QuadPart=0;CHECK(SUCCEEDED(clone->Seek(p,STREAM_SEEK_CUR,&pos)));CHECK(pos.QuadPart==9);ReleaseStgMedium(&m);}
TEST(virtual_file_short_stream_rejected){const BYTE bytes[]{'a','b','c'};ComPtr<IStream>stream;stream.Attach(SHCreateMemStream(bytes,3));auto path=std::filesystem::temp_directory_path()/L"Crackhood-stage-short.bin";auto result=stage_virtual_file(stream.Get(),path,4);std::filesystem::remove(path);CHECK(result==STG_E_READFAULT);}
TEST(virtual_file_verified_size){const BYTE bytes[]{'a','b','c'};ComPtr<IStream>stream;stream.Attach(SHCreateMemStream(bytes,3));auto path=std::filesystem::temp_directory_path()/L"Crackhood-stage-valid.bin";auto result=stage_virtual_file(stream.Get(),path,3);auto size=std::filesystem::file_size(path);std::filesystem::remove(path);CHECK(SUCCEEDED(result));CHECK(size==3);}
